Admin::requirePermission('orders.view');$pdo=db();$error='';$id=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){Security::requireCsrf();Admin::requirePermission('orders.manage');$target=(string)($_POST['status']??'');$reason=trim((string)($_POST['reason']??''));$allowed=['new'=>['reviewing','accepted','rejected','cancelled'],'reviewing'=>['accepted','rejected','cancelled'],'accepted'=>['preparing','ready','cancelled'],'preparing'=>['ready','cancelled'],'ready'=>['completed','cancelled']];try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT * FROM orders WHERE id=? FOR UPDATE");$q->execute([$id]);$order=$q->fetch();if(!$order)throw new RuntimeException('الطلب غير موجود.');$old=$order['status'];if(!in_array($target,$allowed[$old]??[],true))throw new RuntimeException('انتقال حالة الطلب غير مسموح.');if($target==='rejected'&&mb_strlen($reason)<4)throw new RuntimeException('اكتب سبب الرفض بوضوح.');
 $q=$pdo->prepare("SELECT product_id,quantity,product_name_snapshot FROM order_items WHERE order_id=? ORDER BY product_id FOR UPDATE");$q->execute([$id]);$lines=$q->fetchAll();
 if($target==='accepted'){foreach($lines as $line){if(!$line['product_id'])throw new RuntimeException('أحد المنتجات لم يعد موجوداً.');$p=$pdo->prepare("SELECT stock_quantity,reserved_quantity FROM products WHERE id=? FOR UPDATE");$p->execute([$line['product_id']]);$stock=$p->fetch();if(!$stock||((int)$stock['stock_quantity']-(int)$stock['reserved_quantity'])<(int)$line['quantity'])throw new RuntimeException('المخزون غير كافٍ للمنتج: '.$line['product_name_snapshot']);$pdo->prepare("UPDATE products SET reserved_quantity=reserved_quantity+? WHERE id=?")->execute([$line['quantity'],$line['product_id']]);$pdo->prepare("INSERT INTO inventory_movements(product_id,user_id,order_id,movement_type,quantity,note) VALUES(?,?,?,'reserve',?,'حجز كمية لطلب مقبول')")->execute([$line['product_id'],$_SESSION['admin_user']['id'],$id,$line['quantity']]);}}
 if(in_array($target,['rejected','cancelled'],true)&&in_array($old,['accepted','preparing','ready'],true)){foreach($lines as $line){if(!$line['product_id'])continue;$p=$pdo->prepare("SELECT reserved_quantity FROM products WHERE id=? FOR UPDATE");$p->execute([$line['product_id']]);$reserved=(int)$p->fetchColumn();$release=min($reserved,(int)$line['quantity']);if($release>0){$pdo->prepare("UPDATE products SET reserved_quantity=reserved_quantity-? WHERE id=?")->execute([$release,$line['product_id']]);$pdo->prepare("INSERT INTO inventory_movements(product_id,user_id,order_id,movement_type,quantity,note) VALUES(?,?,?,'release',?,'تحرير حجز طلب مرفوض أو ملغى')")->execute([$line['product_id'],$_SESSION['admin_user']['id'],$id,$release]);}}}
 if($target==='completed'){foreach($lines as $line){if(!$line['product_id'])continue;$p=$pdo->prepare("SELECT stock_quantity,reserved_quantity FROM products WHERE id=? FOR UPDATE");$p->execute([$line['product_id']]);$stock=$p->fetch();$qty=(int)$line['quantity'];if(!$stock||(int)$stock['reserved_quantity']<$qty||(int)$stock['stock_quantity']<$qty)throw new RuntimeException('تعذر صرف الكمية المحجوزة للمنتج: '.$line['product_name_snapshot']);$pdo->prepare("UPDATE products SET stock_quantity=stock_quantity-?,reserved_quantity=reserved_quantity-? WHERE id=?")->execute([$qty,$qty,$line['product_id']]);$pdo->prepare("INSERT INTO inventory_movements(product_id,user_id,order_id,movement_type,quantity,note) VALUES(?,?,?,'out',?,'صرف عند إتمام الطلب')")->execute([$line['product_id'],$_SESSION['admin_user']['id'],$id,$qty]);}}
 $pdo->prepare("UPDATE orders SET status=?,rejection_reason=? WHERE id=?")->execute([$target,$target==='rejected'?$reason:null,$id]);$pdo->prepare("INSERT INTO order_status_history(order_id,user_id,old_status,new_status,note) VALUES(?,?,?,?,?)")->execute([$id,$_SESSION['admin_user']['id'],$old,$target,$reason?:null]);$pdo->commit();Admin::audit('order.status','order',$id,['from'=>$old,'to'=>$target]);header('Location: order.php?id='.$id.'&updated=1');exit;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'تعذر تحديث الطلب.';}}
$q=$pdo->prepare("SELECT o.*,c.full_name,c.phone,c.email FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.id=?");$q->execute([$id]);$order=$q->fetch();if(!$order){http_response_code(404);exit('الطلب غير موجود.');}
$q=$pdo->prepare("SELECT * FROM order_items WHERE order_id=?");$q->execute([$id]);$items=$q->fetchAll();$q=$pdo->prepare("SELECT h.*,u.name user_name FROM order_status_history h LEFT JOIN users u ON u.id=h.user_id WHERE h.order_id=? ORDER BY h.id DESC");$q->execute([$id]);$history=$q->fetchAll();
$next=['new'=>['reviewing'=>'بدء المراجعة','accepted'=>'قبول الطلب','rejected'=>'رفض الطلب','cancelled'=>'إلغاء الطلب'],'reviewing'=>['accepted'=>'قبول الطلب','rejected'=>'رفض الطلب','cancelled'=>'إلغاء الطلب'],'accepted'=>['preparing'=>'بدء التجهيز','ready'=>'جاهز للشحن/الاستلام','cancelled'=>'إلغاء الطلب'],'preparing'=>['ready'=>'جاهز للشحن/الاستلام','cancelled'=>'إلغاء الطلب'],'ready'=>['completed'=>'إتمام الطلب','cancelled'=>'إلغاء الطلب']][$order['status']]??[];
