?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>طلب <?=e($order['order_number'])?></title><link rel="stylesheet" href="../assets/css/store.css"><style>.wrap{max-width:1050px;margin:30px auto;padding:0 16px}.panel{background:#111;border:1px solid #49371c;border-radius:14px;padding:20px;margin:16px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.line{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #342718}.table{width:100%;border-collapse:collapse}.table td,.table th{text-align:right;padding:10px;border-bottom:1px solid #342718}.actions{display:flex;gap:8px;flex-wrap:wrap}.actions form{display:flex;gap:8px}.actions select,.actions textarea{background:#080808;color:white;border:1px solid #49371c;padding:9px;border-radius:8px}.actions textarea{min-width:220px}@media(max-width:650px){.grid{grid-template-columns:1fr}.table{font-size:12px}}</style></head><body><main class="wrap"><a class="text-link" href="orders.php">← الطلبات</a><h1>طلب <?=e($order['order_number'])?></h1><?php if($error):?><div class="notice"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['updated'])):?><div class="notice">تم تحديث حالة الطلب والمخزون.</div><?php endif;?><section class="panel grid"><div><h3>بيانات العميل</h3><p><?=e($order['full_name'])?></p><p><?=e($order['phone'])?></p><p><?=e($order['email']??'')?></p><p><?=e($order['city']??'استلام من المحل')?></p><p><?=nl2br(e($order['address']??''))?></p><a class="btn btn-outline" target="_blank" rel="noopener" href="https://wa.me/<?=e($wa)?>?text=<?=$message?>">التواصل عبر واتساب</a></div><div><h3>ملخص الطلب</h3><p>الحالة: <strong><?=e($order['status'])?></strong></p><p>تاريخ الطلب: <?=e($order['created_at'])?></p><p>طريقة الاستلام: <?=e($order['fulfillment_method'])?></p><p>ملاحظات: <?=e($order['customer_note']??'—')?></p><p>سبب الرفض: <?=e($order['rejection_reason']??'—')?></p><p>الإجمالي: <strong style="color:#f4c45e"><?=number_format((float)$order['total'],2)?> ر.س</strong></p></div></section><section class="panel"><h2>المنتجات</h2><table class="table"><thead><tr><th>المنتج</th><th>SKU</th><th>الكمية</th><th>سعر الوحدة</th><th>الإجمالي</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=e($it['product_name_snapshot'])?></td><td><?=e($it['sku_snapshot'])?></td><td><?=(int)$it['quantity']?></td><td><?=number_format((float)$it['unit_price'],2)?></td><td><?=number_format((float)$it['line_total'],2)?></td></tr><?php endforeach;?></tbody></table><div class="line"><span>المجموع</span><b><?=number_format((float)$order['subtotal'],2)?> ر.س</b></div><div class="line"><span>التوصيل</span><b><?=number_format((float)$order['delivery_fee'],2)?> ر.س</b></div></section><?php if($next):?><section class="panel"><h2>تحديث حالة الطلب</h2><form method="post" class="actions"><input type="hidden" name="_csrf" value="<?=e(Security::csrfToken())?>"><select name="status" required><?php foreach($next as $value=>$label):?><option value="<?=e($value)?>"><?=e($label)?></option><?php endforeach;?></select><textarea name="reason" placeholder="سبب الرفض (إلزامي عند الرفض)"></textarea><button class="btn btn-gold">تنفيذ التحديث</button></form><small>يتم حجز المخزون عند القبول، وصرفه عند الإتمام، وتحريره عند الرفض أو الإلغاء.</small></section><?php endif;?><section class="panel"><h2>سجل الحالات</h2><?php foreach($history as $h):?><div class="line"><span><?=e($h['old_status']??'—')?> ← <?=e($h['new_status'])?> · <?=e($h['user_name']??'النظام')?> · <?=e($h['created_at'])?></span><small><?=e($h['note']??'')?></small></div><?php endforeach;?></section><button class="btn btn-outline" onclick="window.print()">طباعة الطلب</button></main></body></html>